import{z as A,x as B,o as n,c as d,q as t,j as i,D as e,d as r,s as l,S as o,b as E}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"完美散列","description":"","frontmatter":{"title":"完美散列","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/perfect-hashing.md","filePath":"cs/perfect-hashing.md","lastUpdated":1791413859000}'),p={name:"cs/perfect-hashing.md"};function m(h,a,c,_,f,u){const s=B("Mermaid");return n(),d("div",null,[a[2]||(a[2]=t('<h1 id="完美散列" tabindex="-1">完美散列 <a class="header-anchor" href="#完美散列" aria-label="Permalink to &quot;完美散列&quot;">​</a></h1><div class="epigraph"><p>键集已知且不再变：可以造一张没有碰撞的表，查找最坏常数次探测。</p><footer>—— 据 Fredman, Komlós and Szemerédi, Storing a Sparse Table with O(1) Worst Case Access Time, JACM 1984；Cormen, Leiserson, Rivest and Stein 整理</footer></div><p><a href="/cs/universal-hashing">上一课</a> 保证期望，单次仍可能撞。<a href="/cs/robin-cuckoo">布谷</a> 最坏查找常数但插入可能重建。静态只读字典（保留字、协议码点）可以预处理到零碰撞。本课不换种子对抗。缺口是完美散列：FKS 两级，或 CHD 等实践方案点名。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>静态集 \\(S\\)，\\(|S|=n\\)，成员查询。完美：\\(h\\) 在 \\(S\\) 上单射。最小完美：值域也是 \\(n\\) 槽。FKS：一级 \\(h\\) 把键分桶，桶 \\(i\\) 大小 \\(n_i\\)，二级表长 \\(\\Theta(n_i^2)\\) 使桶内完美（期望二级空间合计 \\(O(n)\\)）。缺口是<strong>用空间换掉运行时碰撞</strong>，查找两次散列最坏 \\(O(1)\\)。</p><p><span class="marginnote">数字实例：把 1000 个键分进 1000 个桶，期望多数桶只有一两个键；二级表长取 \\(n_i^2\\)，某桶 2 个键就开 4 个槽。各桶平方一加，总量仍是几千个槽的量级——这正是「期望合计 \\(O(n)\\)」的具体长相。</span></p><p><span class="marginnote">Fredman–Komlós–Szemerédi, <em>JACM</em>, 1984。实践 gperf、CHD、BBHash 等，本课不把压缩完美散列论文逐篇列成百科。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>构造：反复抽通用 \\(h\\) 直到一级桶的 \\(\\sum n_i^2=O(n)\\)，每桶再抽二级 \\(h_i\\)。失败重抽，期望尝试常数。查询：一级下标，二级下标，比较键（避免假命中）。</p><p><span class="marginnote">术语翻译：「假命中」就是两个不同的键恰好落到同一槽、读出了别人的值，所以最后必须把存下的键取出来比一次才算数。「重抽」则像掷骰子掷到分桶均匀为止——通用族保证期望掷常数次就能中。</span></p>',10)),(n(),i(o,null,{default:e(()=>[l(s,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E9%9D%99%E6%80%81%E9%94%AE%E9%9B%86%20S%22%5D%20--%3E%20H1%5B%22%E4%B8%80%E7%BA%A7%E5%88%86%E6%A1%B6%22%5D%0A%20%20H1%20--%3E%20H2%5B%22%E6%AF%8F%E6%A1%B6%E5%B9%B3%E6%96%B9%E7%A9%BA%E9%97%B4%E5%AE%8C%E7%BE%8E%22%5D%0A%20%20H2%20--%3E%20Q%5B%22%E6%9C%80%E5%9D%8F%20O(1)%20%E6%9F%A5%E6%89%BE%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"与开放寻址：完美无墓碑、无聚集，但不能插入新键除非重建。与布隆：完美无假阳性，但必须存键或确认比较。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[r("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"空间 \\(O(n)\\) 词级；最小完美更省槽但构造更烦。更新：任意插入可能破坏单射，合同是静态。通用族保证能抽到好 \\(h\\)。",-1)),(n(),i(o,null,{default:e(()=>[l(s,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20LR%0A%20%20subgraph%20ORD%5B%22%E6%99%AE%E9%80%9A%E9%93%BE%E5%9C%B0%E5%9D%80%22%5D%0A%20%20%20%20A1%5B%22%E6%96%B0%E9%94%AE%E9%9A%8F%E6%97%B6%E6%8F%92%E5%85%A5%22%5D%20--%3E%20A2%5B%22%E5%8F%AF%E8%83%BD%E6%92%9E%E4%B8%8A%E8%B6%8A%E6%8B%89%E8%B6%8A%E9%95%BF%E7%9A%84%E9%93%BE%22%5D%0A%20%20%20%20A2%20--%3E%20A3%5B%22%E6%9C%80%E5%9D%8F%E6%9F%A5%E8%AF%A2%20O(n)%22%5D%0A%20%20end%0A%20%20subgraph%20FKSG%5B%22FKS%20%E4%B8%A4%E7%BA%A7%22%5D%0A%20%20%20%20B1%5B%22%E6%9E%84%E9%80%A0%E6%9C%9F%E9%87%8D%E6%8A%BD%E5%88%B0%E5%88%86%E6%A1%B6%E5%9D%87%E5%8C%80%22%5D%20--%3E%20B2%5B%22%E6%A1%B6%20i%20%E5%BC%80%20n_i%5E2%20%E4%B8%AA%E4%BA%8C%E7%BA%A7%E6%A7%BD%22%5D%0A%20%20%20%20B2%20--%3E%20B3%5B%22%E8%BF%90%E8%A1%8C%E6%97%B6%E9%9B%B6%E7%A2%B0%E6%92%9E%2C%20%E4%B8%A4%E6%AC%A1%E6%95%A3%E5%88%97%E5%87%BA%E7%BB%93%E6%9E%9C%22%5D%0A%20%20end%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=t('<p>槽位增减、缓存分布式：下一课一致性哈希，问题从「碰撞」换成「谁负责这个键」。</p><p><span class="marginnote">常见误区：初学者容易以为完美散列是「查询时更快地解决碰撞」——其实碰撞在构造期就被消灭了，运行时一次都不发生。代价也在这：键集一变（哪怕只插一个键），单射可能失效，整表得重建。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不要求交 FKS 实现作业。动态完美散列存在但复杂，主干不提前。过滤器允许误差，后面草图课再放宽。</p><p>后课默认：静态只读无碰撞用完美散列。节点增减时的键映射用一致性哈希。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>完美散列：静态集最坏 \\(O(1)\\)，FKS 两级期望线性空间。</li><li>不能廉价插入。</li><li>分布式槽重映射是一致性哈希。</li><li>出处：Fredman, Komlós and Szemerédi, <em>JACM</em>, 1984；Cormen et al.。</li></ul>',7))])}const C=A(p,[["render",m]]);export{S as __pageData,C as default};
